CLASS_KEY = {'admin': 'admin_key_ref', 'user': 'user_key_ref'}

def _key_for(tenant_id, token_class, db):
    m = db.key_map(tenant_id)
    if token_class not in CLASS_KEY:
        raise ValueError('token_class must be admin or user')
    return m[CLASS_KEY[token_class]]

def wrap_data_key(tenant_id, token_class, data_key, kms, db):
    return kms.encrypt(_key_for(tenant_id, token_class, db), data_key)

def unwrap_data_key(tenant_id, token_class, wrapped, kms, db, audit):
    ref = _key_for(tenant_id, token_class, db)
    try:
        return kms.decrypt(ref, wrapped)
    except kms.AccessDenied:
        # tricky part: a denial is a signal, not a retry case
        audit.write(tenant_id, role=kms.caller_role(), key_ref=ref, op='decrypt', outcome='denied')
        raise

def drift(live_policies, repo_policies):
    return {k: (live_policies.get(k), v) for k, v in repo_policies.items()
            if live_policies.get(k) != v}

