import re, tomllib

def names_in(tool):
    out = {tool.name}
    out |= set(tool.input_schema.get('properties', {}))
    out |= set(tool.output_schema.get('properties', {})) if tool.output_schema else set()
    return out

def audit_tools(tools, deny, canary, call):
    bad = []
    rx = re.compile('|'.join(deny.name_patterns), re.I)
    for t in tools:
        if t.name in deny.allowed:
            continue
        for n in names_in(t):
            if rx.search(n):
                bad.append(f'{t.name}: name {n!r} matches deny pattern')
        # tricky part: a harmless name can still return a secret, so probe with a canary
        if t.read_only:
            out = call(t.name, t.sample_args)
            if canary in repr(out):
                bad.append(f'{t.name}: canary secret appeared in output')
    return bad

def test_no_credential_tools(live_server, deny, canary):
    tools = live_server.list_tools()
    assert audit_tools(tools, deny, canary, live_server.call) == []
    assert any(t.name == 'search' for t in tools)  # an empty list must not pass

