import math, re
from collections import Counter

TOKEN = re.compile(r'[A-Za-z0-9+/=_\-]{20,}')
KEYWORD = re.compile(r'(key|secret|token|password)\W{0,3}$', re.I)
THRESH = {'hex': 3.0, 'b64': 4.5}  # tune on labelled data

def entropy(s):
    n = len(s)
    return -sum(c / n * math.log2(c / n) for c in Counter(s).values())

def charset(s):
    return 'hex' if re.fullmatch(r'[0-9a-fA-F]+', s) else 'b64'

def scan(text, path, rules):
    hits = []
    for r in rules:
        for m in r.rx.finditer(text):
            hits.append((r.id, m.start(), m.end()))
    for m in TOKEN.finditer(text):
        tok = m.group()
        near = text[max(0, m.start() - 40):m.start()]
        if KEYWORD.search(near) and entropy(tok) >= THRESH[charset(tok)]:
            hits.append(('entropy', m.start(), m.end()))
    out = text
    for rid, a, b in sorted(hits, key=lambda h: -h[1]):  # tricky part: mask from the end
        out = out[:a] + f'[SECRET:{rid}]' + out[b:]
    return out, hits, (path == 'output' and bool(hits))

