package brain.scope

import rego.v1

default allow := false

all_legs := {"P", "U", "O"}

# legs the session already holds plus legs this tool adds
new_legs := object.get(data.session_legs, input.task_id, set()) | tool_legs

tool_legs := {l | some l in data.tools[input.tool].legs}

# tricky part: an untagged tool is treated as adding U and O
tool_legs := {"U", "O"} if not data.tools[input.tool]

in_scope if {
    input.tool in data.agents[input.agent_id].tools
    input.zone in data.agents[input.agent_id].zones
}

trifecta if new_legs == all_legs

allow if {
    in_scope
    not trifecta
}

allow if {
    in_scope
    trifecta
    input.approval != ""
}

deny_reason := "trifecta" if trifecta
deny_reason := "out_of_scope" if not in_scope

