import ipaddress, socket
from urllib.parse import urlsplit
from markdown_it import MarkdownIt

md = MarkdownIt('commonmark', {'html': False})

def sanitize_answer(text):
    tokens = md.parse(text)
    out = []
    for t in tokens:
        for ch in (t.children or [t]):
            if ch.type == 'image':
                out.append(ch.content)  # keep alt text, drop the URL
            elif ch.type in ('html_inline', 'html_block'):
                continue  # drop raw html
            elif ch.type == 'link_open':
                out.append('')  # link text stays; the target is dropped
            elif ch.type == 'link_close':
                out.append(' (source: see pointer)')
            elif ch.type in ('text', 'code_inline'):
                out.append(ch.content.replace('http://', 'hxxp://').replace('https://', 'hxxps://'))
            elif ch.type == 'softbreak':
                out.append('\n')
    return ''.join(out)

def egress_allowed(allow, tenant, url):
    u = urlsplit(url)
    host = (u.hostname or '').encode('idna').decode().lower()
    if u.scheme != 'https' or (u.port or 443) != 443 or host not in allow.hosts(tenant):
        return False
    ip = ipaddress.ip_address(socket.gethostbyname(host))  # tricky part: check the resolved address
    return not (ip.is_private or ip.is_link_local or ip.is_loopback)
